set -eu
sudo -n /usr/bin/python3 -I - <<'REVIEWED_INSTALLER'
import base64, hashlib, json, os, pathlib, socket, stat, subprocess, sys

assert os.geteuid() == 0 and socket.gethostname() == 'instance-20260408-091840'
OPS = pathlib.Path('/usr/local/lib/timeline-native-ops')
ROOT = pathlib.Path('/var/lib/timeline-native-app')
UNITS = pathlib.Path('/etc/systemd/system')
SAVED = ROOT / 'controllers-before-6c70'
ENV = {'PATH': '/usr/sbin:/usr/bin:/sbin:/bin', 'LANG': 'C.UTF-8'}

def directory(path):
    for node in [*reversed(path.parents), path]:
        info = node.lstat()
        assert stat.S_ISDIR(info.st_mode) and info.st_uid == 0 and info.st_mode & 0o022 == 0

def read(path):
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    try:
        before = os.fstat(fd)
        assert stat.S_ISREG(before.st_mode) and before.st_nlink == 1 and before.st_uid == 0
        assert stat.S_IMODE(before.st_mode) == 0o644 and before.st_size <= 200000
        with os.fdopen(fd, 'rb', closefd=False) as stream:
            raw = stream.read(200001)
        after = os.fstat(fd)
        assert len(raw) == before.st_size and (before.st_size, before.st_mtime_ns, before.st_ctime_ns) == (after.st_size, after.st_mtime_ns, after.st_ctime_ns)
        return raw
    finally:
        os.close(fd)

def sync(path):
    fd = os.open(path, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)

def write(path, raw, mode):
    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, mode)
    try:
        os.fchmod(fd, mode)
        with os.fdopen(fd, 'wb', closefd=False) as stream:
            stream.write(raw)
            stream.flush()
            os.fsync(fd)
    finally:
        os.close(fd)
    sync(path.parent)

for path in (OPS, ROOT, UNITS):
    directory(path)
assert stat.S_IMODE(ROOT.stat().st_mode) == 0o700
EXPECTED = {'native_backup_controller.py': '5bfda36db359474f5ef218ab3d2b103fbd2acefea49757fcac25494ce3a3874d', 'native_candidate_check.py': '3d28bdf044c3326f0ccead5f8433e2d068ccd7cb8b63ae24a7682c54f86dd944', 'native_cutover.py': '9f7f65d208eb3ce0c3838bafdc7dd33a8f81e1d95da6e05a219b48f753cfd5a5', 'native_database_scope.py': 'e44fad1b0554569e215d7e3ea3bf3d1ab2c11a35c62a14949c7d05900cc76dcc', 'native_migration_probe.py': '375ce24629be5f40cfe106ebea736a3c69d8f4b23ea3f77b141f9b90cc351dab', 'native_runtime_app.py': '8fec80a41357d99893a528742fec826e1ca9dfec23f7f685fb821dc219a4abec', 'native_runtime_network.py': 'd85f6a2ff101c1180b56b059b313571b38f84ddbeca8c1b213f2a20a96020807', 'native_runtime_redis.py': 'e21b6e15c3a50c345f60f8c31f65c7bbfe245a77ffacf2403568bffd54a8cbbc'}
PAYLOAD = json.loads(base64.b64decode('', validate=True))
NAMES = ('native_release.py', 'native_runtime_app.py', 'native_cutover.py', 'timeline-native-release.service', 'timeline-native-release-check.service', 'timeline-native-release-rollback.service')
assert set(PAYLOAD) == set(NAMES)
old = {name: read(OPS / name) for name in EXPECTED}
assert all(hashlib.sha256(old[name]).hexdigest() == digest for name, digest in EXPECTED.items())
for name in NAMES:
    item = PAYLOAD[name]
    assert set(item) == {'sha256', 'text'} and hashlib.sha256(item['text'].encode()).hexdigest() == item['sha256']
    destination = (OPS if name.endswith('.py') else UNITS) / name
    if name not in ('native_runtime_app.py', 'native_cutover.py'):
        assert not os.path.lexists(destination)
    if name.endswith('.py'):
        compile(item['text'], name, 'exec')
assert not os.path.lexists(SAVED) and not os.path.lexists(ROOT / 'release-6c70-state.json')
sys.path.insert(0, str(OPS))
import native_backup_controller as backup
with backup.locked():
    subprocess.run(['/usr/bin/python3', '-I', str(OPS / 'native_cutover.py'), 'check-committed'], env=ENV, check=True, timeout=30)
    for unit in ('timeline-native-api.service', 'timeline-native-web.service', 'timeline-native-api-ingress.socket', 'timeline-native-web-ingress.socket'):
        subprocess.run(['/usr/bin/systemctl', 'is-active', '--quiet', unit], env=ENV, check=True, timeout=20)
    assert all(read(OPS / name) == raw for name, raw in old.items())
    SAVED.mkdir(mode=0o700)
    sync(ROOT)
    for name in ('native_runtime_app.py', 'native_cutover.py'):
        write(SAVED / name, old[name], 0o600)
    # Install new module first. Until release state exists, both old and new
    # controllers select the same OLD native program, including during reboot.
    for name in NAMES:
        destination = (OPS if name.endswith('.py') else UNITS) / name
        raw = PAYLOAD[name]['text'].encode()
        if name in ('native_runtime_app.py', 'native_cutover.py'):
            temporary = OPS / ('.install-6c70-' + name)
            write(temporary, raw, 0o644)
            assert read(destination) == old[name]
            os.replace(temporary, destination)
            sync(OPS)
        else:
            write(destination, raw, 0o644)
        assert read(destination) == raw
    unitpaths = [str(UNITS / name) for name in NAMES if name.endswith('.service')]
    subprocess.run(['/usr/bin/systemd-analyze', 'verify', *unitpaths], env=ENV, check=True, timeout=30)
    subprocess.run(['/usr/bin/systemctl', 'daemon-reload'], env=ENV, check=True, timeout=20)
    subprocess.run(['/usr/bin/python3', '-I', str(OPS / 'native_cutover.py'), 'check-committed'], env=ENV, check=True, timeout=30)
print(json.dumps({'nativeReleaseControllerInstalled': True, 'runtimeChanged': False,
                  'newUnitsStarted': False, 'oldControllersRetained': True,
                  'files': {name: PAYLOAD[name]['sha256'] for name in NAMES}}))

REVIEWED_INSTALLER
